int adj[7][7]; // adjacency matrix

// We need to assign to each vertex a value from 1 to 6 (or 0 if no domino is placed on any edge incident to it)
// But actually, the constraint is: for each vertex, all domino halves directed toward it must have the same number of dots.
// This means each vertex v is assigned a value val[v] in {1,2,3,4,5,6} or 0 (meaning no domino is placed on any edge incident to v).
// For an edge (u,v), if we place a domino, then the domino must be of type (val[u], val[v]) or (val[v], val[u]).
// Since dominoes are undirected in the set (a,b) with a<=b, we can use domino (min(val[u],val[v]), max(val[u],val[v])).
// But we can use each domino type at most once.
// Also, if val[u] == 0 or val[v] == 0, we cannot place a domino on edge (u,v).
// If val[u] == val[v], we can place a domino of type (val[u], val[u]).

// Approach:
// Since n <= 7, we can try all possible assignments of values to vertices.
// Each vertex can have a value from 0 to 6 (0 means no domino on any incident edge).
// Total assignments: 7^7 = 823543, which is manageable.
// For each assignment, we check:
//   1. For each edge (u,v), if val[u] != 0 and val[v] != 0, then we can place a domino of type (min(val[u],val[v]), max(val[u],val[v])).
//   2. We must ensure that no domino type is used more than once.
//   3. Count the number of dominoes placed.
//   4. Keep the maximum count.

// However, note: if val[u] == 0 or val[v] == 0, we simply don't place a domino on that edge.
// Also, if val[u] == val[v] == 0, no domino.

int main() {
    cin >> n >> m;
    memset(adj, 0, sizeof(adj));
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        adj[a][b] = 1;
        adj[b][a] = 1;
    }

    int maxDominoes = 0;
    // Try all assignments: each vertex gets a value from 0 to 6
    // We'll use an array val[7]
    int val[7];

    // We'll iterate over all 7^n possibilities
    // Since n <= 7, 7^7 = 823543
    for (int mask = 0; mask < (1 << (3 * n)); mask++) {
        // Decode the mask to get val[0..n-1]
        // Each value is 0-6, which needs 3 bits
        bool valid = true;
        for (int i = 0; i < n; i++) {
            int bits = (mask >> (3 * i)) & 7;
            val[i] = bits;
            if (val[i] > 6) {
                valid = false;
                break;
            }
        }
        if (!valid) continue;

        // Check if this assignment is valid and count dominoes
        // We need to track which domino types are used
        bool used[7][7] = {}; // used[a][b] for a <= b
        int count = 0;
        bool conflict = false;

        for (int i = 0; i < n && !conflict; i++) {
            for (int j = i + 1; j < n && !conflict; j++) {
                if (adj[i][j]) {
                    if (val[i] == 0 || val[j] == 0) {
                        // No domino placed
                        continue;
                    }
                    int a = min(val[i], val[j]);
                    int b = max(val[i], val[j]);
                    if (used[a][b]) {
                        conflict = true;
                    } else {
                        used[a][b] = true;
                        count++;
                    }
                }
            }
        }

        if (!conflict) {
            maxDominoes = max(maxDominoes, count);
        }
    }

    cout << maxDominoes << endl;
    return 0;
}
